const crypto = require('crypto');

const item = $input.all()[0];
const headers = (item.json && item.json.headers) || {};
const b64 = item.binary && item.binary.data && item.binary.data.data;
const raw = typeof b64 === 'string' ? Buffer.from(b64, 'base64').toString('utf8') : '';
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.LENDLOOP_HMAC_SECRET || '';
const tolerance = Number($env.SIGNATURE_TOLERANCE_SECONDS || 300);

const fail = (reason) => [{ json: { valid: false, reason, body: null } }];

if (!secret) return fail('not_configured');
if (!raw) return fail('missing_body');
if (!/^\d{1,12}$/.test(timestamp)) return fail('bad_timestamp');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > tolerance) return fail('stale');
const match = /^v1=([0-9a-f]{64})$/.exec(signature);
if (!match) return fail('bad_signature');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(match[1]))) return fail('mismatch');

let body;
try {
  body = JSON.parse(raw);
} catch (error) {
  return fail('bad_json');
}
if (!body || typeof body !== 'object') return fail('bad_json');

const email = body.recipient && typeof body.recipient.email === 'string' ? body.recipient.email : '';
const required = [
  body.event,
  body.idempotencyKey,
  body.tool && body.tool.name,
  body.window && body.window.start,
  body.window && body.window.end,
  body.deepLink,
];
if (required.some((value) => typeof value !== 'string' || value.length === 0) || !email.includes('@')) {
  return fail('bad_payload');
}

return [{ json: { valid: true, reason: 'ok', body } }];

const b = $json.body;
const who = b.recipient.name;
const tool = b.tool.name;
const range = b.window.start + ' to ' + b.window.end;

const templates = {
  'request.created': {
    subject: 'Someone wants to borrow your ' + tool,
    text: 'Hi ' + who + ',\n\nA neighbour has asked to borrow your ' + tool + ' for ' + range + '.\n\nOpen your incoming requests to approve or decline:\n' + b.deepLink + '\n\n— LendLoop',
  },
  'request.approved': {
    subject: 'Approved: your ' + tool + ' for ' + range,
    text: 'Hi ' + who + ',\n\nYour request for ' + tool + ' (' + range + ') was approved. Arrange pickup with the owner.\n\n' + b.deepLink + '\n\n— LendLoop',
  },
  'request.declined': {
    subject: 'Declined: your ' + tool + ' for ' + range,
    text: 'Hi ' + who + ',\n\nYour request for ' + tool + ' (' + range + ') was declined. Browse other tools for those dates:\n' + b.deepLink + '\n\n— LendLoop',
  },
  'request.cancelled': {
    subject: 'Withdrawn: ' + tool + ' for ' + range,
    text: 'Hi ' + who + ',\n\nThe request for your ' + tool + ' (' + range + ') was withdrawn by the borrower.\n\n' + b.deepLink + '\n\n— LendLoop',
  },
  'request.returned': {
    subject: tool + ' is back and relisted',
    text: 'Hi ' + who + ',\n\n' + tool + ' has been marked returned and is available again.\n\n' + b.deepLink + '\n\n— LendLoop',
  },
};

const template = templates[b.event];
return [{
  json: {
    to: b.recipient.email,
    subject: template ? template.subject : 'LendLoop update',
    text: template ? template.text : 'There is an update on your LendLoop request: ' + b.deepLink,
  },
}];
